import{openAuditPage,pause}from'/workspace/trading101/docs/adsense-2026-10-22/browser-session.mjs';import{mkdirSync,writeFileSync}from'node:fs';const[origin,sha,stage,port,theme]=process.argv.slice(2);const root='/workspace/trading101/docs/adsense-2026-10-22/evidence/',folder=root+'learn-path-contrast-'+stage+'-20261030',p=await openAuditPage('about:blank',Number(port)),rows=[];mkdirSync(folder,{recursive:true});p.onEvent(m=>{if(m.method==='Fetch.requestPaused'){const{requestId,request}=m.params,u=new URL(request.url),safe=['GET','HEAD','OPTIONS'].includes(request.method)||(request.method==='POST'&&['/rest/v1/rpc/get_public_practice_members','/rest/v1/rpc/get_published_course_catalog'].includes(u.pathname));p.send(safe?'Fetch.continueRequest':'Fetch.failRequest',safe?{requestId}:{requestId,errorReason:'Aborted'}).catch(()=>{});}});await p.send('Fetch.enable',{patterns:[{urlPattern:'https://*.supabase.co/*',requestStage:'Request'}]});for(const width of[360,390,768,1280,1920]){await p.send('Emulation.setDeviceMetricsOverride',{width,height:900,deviceScaleFactor:1,mobile:width<500});await p.send('Page.navigate',{url:origin+'/learn'});await p.wait("!!document.querySelector('main h1')&&!document.querySelector('#prerender-seo')");await p.evaluate('document.fonts.ready.then(()=>true)',true);await pause(1600);await p.evaluate("[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reject analytics')?.click();true");const targets=await p.evaluate("[...document.querySelectorAll('main span,main h3')].filter(e=>/^(Step [1-3]|Foundations|Strategy & Analysis|Advanced Practice)$/.test(e.textContent.trim())).map((e,i)=>{const s=getComputedStyle(e),layers=[];for(let x=e;x;x=x.parentElement){const q=getComputedStyle(x);layers.push({tag:x.tagName,background:q.backgroundColor,image:q.backgroundImage,opacity:q.opacity});if(q.backgroundColor.startsWith('rgb('))break;}return{text:e.textContent,color:s.color,font:s.fontSize,weight:s.fontWeight,layers,y:Math.max(0,scrollY+e.getBoundingClientRect().top-150)}})");for(const i of[0,2]){await p.evaluate(`scrollTo(0,${targets[i].y});true`);await pause(700);const screenshot=`path-${i}-${width}-${theme}.png`;await p.screenshot(folder+'/'+screenshot);}rows.push({width,theme:await p.evaluate("document.documentElement.classList.contains('light')?'light':'dark'"),targets});}writeFileSync(root+'LEARN-PATH-CONTRAST-'+stage.toUpperCase()+'-'+theme.toUpperCase()+'-20261030.json',JSON.stringify({checkedAt:new Date().toISOString(),sha,origin,outcome:'COLLECTED_REQUIRES_CONTRAST_AND_PERSONAL_REVIEW',rows,scope:'Actual current public read-only layout/foreground/solid-background layers for learning-path labels. Before screenshots require personal viewing and contrast calculation. No button/link/data changes except disposable-browser analytics rejection; protected requests blocked.'},null,2)+'\n');await p.close();
